/// <summary>
/// Retrives delivery instructions
/// </summary>
/// <returns>Delivery instructions</returns>
public METDeliveryInstructions getDeliveryInstructions()
{
    METDeliveryInstructions ret = metSalesTable.DeliveryInstructions;

    return ret;
}

/// <summary>
/// Retrives the Transfer order type
/// </summary>
/// <returns>Transfer type</returns>
public METCrossDockTransferType getTransferType()
{
    METCrossDockTransferType ret = metSalesTable.InternalCrossDockOrder == NoYes::Yes ? METCrossDockTransferType::CrossDock : METCrossDockTransferType::CSD;

    return ret;
}

/// <summary>
/// Retrives door and staging lane id
/// </summary>
/// <returns>container with door and staging lane id</returns>
public container getDoorAndLane()
{
    container ret;
    METStagingLane stagingLane = metSalesTable.StagingLaneId;
    METDoorIdentifier door;

    if (metSalesTable.InternalCrossDockOrder == NoYes::Yes &&
                finalLegTransferTableExt.TransferType ==  METCrossDockTransferType::CrossDock)
    {
        stagingLane = metSalesTable.SecondaryStagingLaneId;
        door = any2Str(metSalesTable.SecondaryDoorNum);
    }
    return [door, stagingLane];
}

/// <summary>
/// Get the route details
/// </summary>
/// <returns>Container with route details</returns>
public container getRouteDetails()
{
    container ret = [metSalesTable.SecondRoute, metSalesTable.SecondRouteStopNum,
                metSalesTable.OriginalSecondRouteIdentifier, metSalesTable.OriginalSecondRouteStopIdentifier];

    return ret;
}

/// <summary>
/// update TMS related data
/// </summary>
public void updateTMSData(InventTransferTable _transferTable)
{
    super(_transferTable);
    //CB627_TMSEngineProcessingTOCreation
    TMSInventTransferTable  tmsTransferTable;
    TMSSalesTable           tmsSalesTable = TMSSalesTable::find(this.getSoruceId());

    tmsTransferTable = TMSInventTransferTable::find(_transferTable.TransferId);

    if(tmsTransferTable)
    {
        tmsTransferTable.selectForUpdate(true);
        tmsTransferTable.setCarrierFields(this.getCarrierCode(), this.getCarriedServiceCode());
        tmsTransferTable.update();
    }
    else
    {
        tmsTransferTable.initFromInventTransferId(_transferTable.TransferId);
        tmsTransferTable.setCarrierFields(this.getCarrierCode(), this.getCarriedServiceCode());
        tmsTransferTable.insert();
    }
}

/// <summary>
/// Get extraction status to be set
/// </summary>
/// <returns>Order extraction status</returns>
public METOrderExtractStatus getExtractionStatus()
{
    METOrderExtractStatus ret;

    ret = super();

    if (metSalesLine.OrderExtractStatus == METOrderExtractStatus::Extracted)
    {
        ret = METOrderExtractStatus::ReadyForExtract;
    }

    return ret;
}

/// <summary>
/// Sets the reference data
/// </summary>
/// <param name = "_transLineExt"><t>METInventTransferLine</t> table buffer</param>
protected void setSourceLineReference(METInventTransferLine _transLineExt)
{
    _transLineExt.SalesLineTransId = this.getSourceTransId();
    _transLineExt.SalesId = this.getSoruceId();
}

/// <summary>
/// Should substitution be allowed for this order
/// </summary>
/// <returns>true, if substitution allowed otherwise false</returns>
public NoYes shouldAllowSubstitution()
{
    NoYes ret;
    // Allow substitution only when,
    // 1. Metcash sales order type allows substitution
    // 2. No quantity is reserved on the origin sales line

    ret = super();

    METSalesOrderTypes metOrderType = salesTable.METSalesOrderTypes();
    if (metOrderType && metOrderType.SubstitutesAllowed == NoYes::Yes)
    {
        ret = this.getReservedQty() == 0 ? NoYes::Yes : NoYes::No;
    }
    else
    {
        ret = NoYes::No;
    }

    return ret;
}

/// <summary>
/// Should the transfer order be received automatically
/// </summary>
/// <returns>true, if the order should be auto-received otherwise, false</returns>
public boolean shouldAutoReserve()
{
    boolean ret = (inventParameter.InventTransferAutoReservation || metSalesTable.EventID != '');

    return ret;
}

/// <summary>
/// Get confirmed shipdate
/// </summary>
/// <returns>Confirmed shipment date</returns>
public TransDate getConfirmedShipDate()
{
    TransDate ret = salesTable.ShippingDateConfirmed;

    return ret;
}

public void init(Common _sourceRecord)
{
    if (_sourceRecord.TableId == tableNum(SalesTable))
    {
        salesTable = _sourceRecord;
    }
    else if(_sourceRecord.TableId == tableNum(SalesLine))
    {
        salesLine = _sourceRecord;
    }
}

/// <summary>
/// Update PDS quantity details
/// </summary>
/// <param name = "_transferLine"><t>InventTransferLine</t> buffer</param>
public void updatePDSQuantity(InventTransferLine _transferLine)
{
    if (salesLine.PdsCWQty)
    {
        _transferLine.PdsCWQtyTransfer = salesLine.pdsCWQtyActivateRemainder();
        _transferLine.modifiedField(fieldNum(InventTransferLine, PdsCWQtyTransfer));
    }
}

/// <summary>
///
/// </summary>
/// <param name = "_transferLine"></param>
public void updateMarking(InventTransferLine _transferLine)
{
    // Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
    // Commented FC confirmed not to use preview feature
    _transferLine.metCheckAndUpdateMarking(this.getSourceTransId());
}

/// <summary>
/// Init transfer order line from source record.
/// </summary>
/// <param name = "_transLine"><t>InventTransLine</t> buffer</param>
public void initTransferOrderLine(InventTransferLine _transLine)
{
    _transLine.initFromSalesLine(salesLine);

    super(_transLine);
}

