/// <summary>
/// Primarily used to create transfer order lines during substitution process. As the substitution will process each sales lines
/// </summary>
/// <param name = "_salesLine"></param>
public void CreateTransferOrderFromSalesLine(SalesLine _salesLine)
{
    metSalesLine = _salesLine.metSalesLine();
    salesLine = _salesLine;

    // Bug 225259: CB238 - NDC / Int xDock: D365 functional warehouse processing Liquor LE SO extraction and TO extraction LSE004 and LTE003 substitution issues
    // When called from subs, the record was not initialised
    inventParameter = InventParameters::find();

    select firstonly salesTable
        where salesTable.SalesId == _salesLine.SalesId
        join metSalesTable
        where metSalesTable.SalesTable == salesTable.RecId;

    ttsbegin;
    this.CreateTransferOrderLine();
    ttscommit;
}

protected InventQty getTransferOrderQty()
{
    return this.getRemainQty() - this.getReservedQty();
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public InventQty getRemainQty()
{
    InventQty ret = salesLine.RemainInventPhysical;

    return ret;
}

/// <summary>
///
/// </summary>
public void updateSourceRecord(InventTransferLine _transferLine)
{
    metSalesLine.selectForUpdate(true);
    metSalesLine.TransferOrderNumber = finalLegTransferTable.TransferId;
    metSalesLine.InventTransIdReceive = _transferLine.InventTransIdReceive;
    metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;

    metSalesLine.update();
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public InventTransId getSourceTransId()
{
    InventTransId ret = salesLine.InventTransId;

    return ret;
}

/// <summary>
/// Get reserved quantity
/// </summary>
/// <returns>Quantity reserved</returns>
public InventQty getReservedQty()
{
    InventQty ret = salesLine.reservedPhysical();;

    return ret;
}

public void CreateTransferOrder()
{
    metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId);
    inventParameter = InventParameters::find();

    ttsbegin;
    while select * from salesLine
        order by metSalesLine.SupplyingWarehouse
        where salesLine.SalesId == salesTable.SalesId &&
              salesLine.SalesStatus != SalesStatus::Canceled //218457 - CB238 - Bug - Liquor extraction Internal Customer not getting updated
        join * from metSalesLine where metSalesLine.SalesLine == salesLine.RecId
        && metSalesLine.LineCancellationRequired == NoYes::No
    {
        this.CreateTransferOrderLine();
    }

    salesTable.metUpdateExtractStatus();

    ttscommit;

    super();
}
